create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'creator' check(role in('creator','brand','admin')),full_name text not null,avatar_url text,bio text,website text,created_at timestamptz default now());
create table if not exists public.creators(id uuid primary key default gen_random_uuid(),profile_id uuid unique not null references public.profiles(id) on delete cascade,handle text unique,category text default 'other',description text,country text,youtube_url text,instagram_url text,x_url text,youtube_followers bigint default 0,instagram_followers bigint default 0,x_followers bigint default 0,engagement_rate numeric(5,2) default 0,verified boolean default false,created_at timestamptz default now());
create table if not exists public.brands(id uuid primary key default gen_random_uuid(),profile_id uuid unique not null references public.profiles(id) on delete cascade,company_name text not null,website text,description text,logo_url text,industry text,country text,created_at timestamptz default now());
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),brand_id uuid not null references public.brands(id) on delete cascade,title text not null,description text not null,category text default 'other',budget_min numeric(12,2),budget_max numeric(12,2),currency text default 'INR',platforms text[] default '{}',requirements text,deadline date,status text default 'open' check(status in('draft','open','paused','closed')),created_at timestamptz default now());
create table if not exists public.campaign_applications(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.campaigns(id) on delete cascade,creator_id uuid references public.creators(id) on delete cascade,pitch text,proposed_fee numeric(12,2),portfolio_url text,status text default 'pending' check(status in('pending','accepted','rejected','withdrawn')),created_at timestamptz default now(),unique(campaign_id,creator_id));
alter table public.profiles enable row level security;alter table public.creators enable row level security;alter table public.brands enable row level security;alter table public.campaigns enable row level security;alter table public.campaign_applications enable row level security;
create policy "public creators read" on public.creators for select using(true);
create policy "public open campaigns read" on public.campaigns for select using(status='open');
create policy "own profile insert" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "own profile read" on public.profiles for select to authenticated using(auth.uid()=id);
create policy "own profile update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "creator own insert" on public.creators for insert to authenticated with check(profile_id=auth.uid());
create policy "creator own update" on public.creators for update to authenticated using(profile_id=auth.uid()) with check(profile_id=auth.uid());
create policy "brand own insert" on public.brands for insert to authenticated with check(profile_id=auth.uid());
create policy "brand own read" on public.brands for select to authenticated using(profile_id=auth.uid());
create policy "brand own update" on public.brands for update to authenticated using(profile_id=auth.uid()) with check(profile_id=auth.uid());
create policy "brand create campaigns" on public.campaigns for insert to authenticated with check(exists(select 1 from public.brands b where b.id=brand_id and b.profile_id=auth.uid()));
create policy "brand update campaigns" on public.campaigns for update to authenticated using(exists(select 1 from public.brands b where b.id=brand_id and b.profile_id=auth.uid()));
create policy "creator apply" on public.campaign_applications for insert to authenticated with check(exists(select 1 from public.creators c where c.id=creator_id and c.profile_id=auth.uid()));
create policy "application parties read" on public.campaign_applications for select to authenticated using(exists(select 1 from public.creators c where c.id=creator_id and c.profile_id=auth.uid()) or exists(select 1 from public.campaigns ca join public.brands b on b.id=ca.brand_id where ca.id=campaign_id and b.profile_id=auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','New User'),coalesce(new.raw_user_meta_data->>'role','creator')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();